BINARY_CHARS = '01'
BYTE_SIZE = 8
ZERO_CHAR = '0'
ONE_CHAR = '1'

class BinaryDataProcessor:
    def __init__(self, binary_string):
        self._binary_string = binary_string
        self._clean_non_binary_chars()

    @property
    def binary_string(self):
        return self._binary_string

    @binary_string.setter
    def binary_string(self, value):
        self._binary_string = value

    def _clean_non_binary_chars(self):
        self._binary_string = ''.join(filter(lambda x: x in BINARY_CHARS, self._binary_string))

    def calculate_binary_info(self):
        total_length = self._get_bit_length()
        if total_length == 0:
            raise ZeroDivisionError("Binary string is empty")

        zeroes_percentage = self._get_zeroes_percentage(total_length)
        ones_percentage = self._get_ones_percentage(total_length)

        return {
            'Zeroes': zeroes_percentage,
            'Ones': ones_percentage,
            'Bit length': total_length
        }

    def _get_bit_length(self):
        return len(self._binary_string)

    def _get_zeroes_count(self):
        return self._binary_string.count(ZERO_CHAR)

    def _get_ones_count(self):
        return self._binary_string.count(ONE_CHAR)

    def _get_zeroes_percentage(self, total_length):
        return self._get_zeroes_count() / total_length

    def _get_ones_percentage(self, total_length):
        return self._get_ones_count() / total_length

    def convert_to_ascii(self):
        return self._decode_bytes('ascii')

    def convert_to_utf8(self):
        return self._decode_bytes('utf-8')

    def _decode_bytes(self, encoding):
        byte_array = self._binary_to_bytearray()
        return byte_array.decode(encoding)

    def _binary_to_bytearray(self):
        byte_array = bytearray()
        for i in range(0, len(self._binary_string), BYTE_SIZE):
            byte = self._binary_string[i:i+BYTE_SIZE]
            if len(byte) < BYTE_SIZE:
                break
            decimal = int(byte, 2)
            byte_array.append(decimal)
        return byte_array
